INSERT INTO providers (id,slug,listing_type,name,description,website_url,source_url,listing_status,claim_status,origin,provider_classification)
SELECT 'independent-danny-bryck','danny-bryck-coaching-independent-danny-bryck','coach','Danny Bryck Coaching','Danny Bryck offers private one-to-one and semi-private or group dialect coaching, including in-person coaching in New York City. New York-based coach, actor, and playwright; BFA in Theatre from Boston University; studied at the London Academy of Music and Dramatic Arts.','https://www.dannybryckcoaching.com/dialect-coaching','https://www.dannybryckcoaching.com/dialect-coaching','published','unclaimed','seeded','independent_teacher'
